  // Configuration remains a page with selection/preview dialogs. File contents
  // stay in local memory and are never added to persisted widget state.
  const cConfigItems=[['ledgers','账本'],['categories','分类'],['accounts','账户'],['tags','标签'],['budgets','预算'],['recurring_transactions','周期账单'],['ai','AI 智能识别配置'],['app_settings','应用设置（语言、外观、提醒、默认账户等）']];
  const cConfig={selected:new Set(cConfigItems.map(x=>x[0])),importSelected:new Set(['tags']),available:new Set(['tags']),importText:"version: 1\ntags:\n  items:\n    - name: 工作日\n      color: '#aa8b29'",fileName:'配置示例.yml'};
  function cConfigYaml(){return 'version: 1\n'+cConfigItems.filter(([id])=>cConfig.selected.has(id)).map(([id])=>id==='ledgers'?'ledgers:\n  items:\n    - name: 日常生活\n      currency: CNY':id==='tags'?"tags:\n  items:\n    - name: 工作日\n      color: '#aa8b29'":id+': {}').join('\n');}
  function cConfigChoices(importing=false){const selected=importing?cConfig.importSelected:cConfig.selected;return `<div class="c-config-options">${cConfigItems.filter(([id])=>!importing||cConfig.available.has(id)).map(([id,label])=>`<label class="v4-control-row" style="font-size:14px;min-height:48px"><span style="flex:1">${esc(label)}${id==='ai'?'<small style="display:block;color:var(--bc-muted);font-size:11px;margin-top:3px">服务商、能力绑定、模型设置等</small>':''}</span><input class="v4-control" type="checkbox" data-c-config="${id}" data-c-import="${importing}" ${selected.has(id)?'checked':''} aria-label="${esc(label)}"></label>`).join('')}</div>`;}
  function cConfigPreview(text){return `<pre class="c-config-preview" style="white-space:pre-wrap;overflow-wrap:anywhere;max-height:220px;overflow:auto;margin:0;padding:12px;border-radius:13px;background:var(--bc-soft);font:11px/1.6 ui-monospace,monospace">${esc(text)}</pre>`;}
  function cConfigScroll(content){return `<div style="max-height:${Math.max(120,qPreview.height-240)}px;overflow:auto">${content}</div>`;}
  const cConfigInfo="此功能用于导出和导入应用配置，包括云服务配置、AI配置等。配置文件采用YAML格式，方便查看和编辑。\n\n⚠️ 配置文件包含敏感信息（如API密钥、密码等），请妥善保管。";
  function cConfigPage(){return `${surface('<h3 style="font-size:15px">功能说明</h3><p class="bc-small" style="line-height:1.6;margin-top:8px;white-space:pre-line">'+esc(cConfigInfo)+'</p>')}${menuCard([['c-config-export','upload','导出配置','将当前配置导出为YAML文件'],['c-config-import','download','导入配置','从YAML文件恢复配置']])}<input type="file" data-c-config-file accept=".yml,.yaml" hidden>${surface('<h3 style="font-size:15px">包含的配置项</h3>'+cConfigItems.map(([,label])=>`<div style="display:flex;gap:9px;align-items:center;padding:6px 0;font-size:13px">${icon('check')}${esc(label)}</div>`).join('')+'<p style="font-size:11px;line-height:1.6;color:var(--bc-muted);margin-top:6px">Supabase 云服务配置 · WebDAV 云服务配置 · S3 云服务配置</p>')}`;}

  fDefs.config.body=cConfigPage;
  const cPreviousModalBody=rModalBody;
  rModalBody=function(key){
    if(key==='config-error'||key==='config-done')return `<p style="font-size:13px;line-height:1.6;margin:0">${key==='config-error'?'配置文件无法解析，请检查文件内容后重试。':'配置已导入，部分配置需要重启应用后生效。'}</p><div class="bc-inline-actions" style="margin-top:16px">${btn('r-close','知道了','知道了','bc-primary')}</div>`;
    if(key==='config-select')return cConfigScroll(cConfigChoices())+rModalActions('r-close','取消','c-config-next','下一步');
    if(key==='config-preview')return cConfigScroll(cConfigPreview(cConfigYaml()))+rModalActions('r-close','取消','c-config-download','确认导出');
    if(key==='config-import')return cConfigScroll(`<div class="f-info" style="margin-bottom:12px">导入将覆盖现有配置，建议先备份当前配置。</div><div class="bc-small" style="margin-bottom:8px">${esc(cConfig.fileName)}</div>${cConfigPreview(cConfig.importText)}<h3 style="margin:12px 0 4px;font-size:14px">选择导入内容</h3>${cConfigChoices(true)}`)+rModalActions('r-close','取消','c-config-confirm-import','确认导入');
    return cPreviousModalBody(key);
  };
  Object.assign(rSpecs,{'config-select':{title:'选择导出内容',host:'flow-config',kind:'dialog'},'config-preview':{title:'导出预览',host:'flow-config',kind:'dialog'},'config-import':{title:'导入预览',host:'flow-config',kind:'dialog'},'config-error':{title:'配置导入失败',host:'flow-config',kind:'dialog'},'config-done':{title:'需要重启',host:'flow-config',kind:'dialog'}});
  for(const [key,title] of [['config-select','选择导出内容'],['config-import','导入预览'],['config-error','配置导入失败'],['config-done','需要重启']]){fDefine(key,title,'导入导出与维护','settings/config_import_export_page.dart',()=>rModalBody(key));let group=[...picker.querySelectorAll('optgroup')].find(g=>g.label==='补齐 · 导入导出与维护');if(!group){group=document.createElement('optgroup');group.label='补齐 · 导入导出与维护';picker.appendChild(group);}group.appendChild(new Option(title+' · 弹窗','flow-'+key));}
  root.addEventListener('change',async e=>{
    if(e.target.matches('[data-c-config]')){const selected=e.target.dataset.cImport==='true'?cConfig.importSelected:cConfig.selected;e.target.checked?selected.add(e.target.dataset.cConfig):selected.delete(e.target.dataset.cConfig);}
    if(e.target.matches('[data-c-config-file]')&&e.target.files[0]){const file=e.target.files[0];if(!/\.ya?ml$/i.test(file.name)){notice('请选择 YAML 文件');return;}cConfig.importText=await file.text();cConfig.fileName=file.name;cConfig.available=new Set(cConfigItems.filter(([id])=>new RegExp('^'+id+':','m').test(cConfig.importText)).map(x=>x[0]));cConfig.importSelected=new Set(cConfig.available);e.target.value='';rOpenModal('config-import');}
  });
  root.addEventListener('click',e=>{const el=e.target.closest('[data-action]');if(!el||!el.dataset.action.startsWith('c-config-'))return;e.preventDefault();e.stopImmediatePropagation();switch(el.dataset.action){case'c-config-export':rOpenModal('config-select');break;case'c-config-next':rDismiss();rOpenModal('config-preview');break;case'c-config-import':phone.querySelector('[data-c-config-file]').click();break;case'c-config-confirm-import':rDismiss();render();rOpenModal('config-done');break;case'c-config-download':{const blob=new Blob([cConfigYaml()],{type:'application/yaml'}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download='beecount-config-demo.yml';a.click();URL.revokeObjectURL(url);rDismiss();render();notice('配置已导出');break;}}},true);
